{"cards": [{"node_code": "N_6a9f5100e2c41f8d", "definition": "研究热力学系统定义、状态参数、过程描述及纯物质、混合物、湿空气等工质物性规律与图表应用的分支。", "boundary": "聚焦于描述系统状态的基础概念与物性数据。涵盖系统边界、状态方程、焓熵等参数定义，以及理想气体、实际气体、湿空气及溶液的性质。与“热力学定律”的区别在于：本节点侧重“是什么”（状态描述与数据），而非“为什么”（能量守恒与方向性）。与“热力过程”的区别在于：本节点侧重静态或准静态状态点的性质，而非过程路径分析。", "includes": ["热力学系统、状态、过程及平衡态的基本概念", "纯物质状态方程、物性图表（如压焓图、温熵图）及湿空气性质", "混合物、溶液及多组分系统的物性关系"], "excludes": ["基于热力学定律的能量平衡计算（归入热力学定律与可用能）", "具体动力循环的效率分析与设计（归入热力过程与动力循环）"], "sibling_distinctions": [{"other_code": "N_e4cbdea8437d2314", "rule": "本节点提供状态参数定义与物性数据基础；兄弟节点研究能量守恒、熵增原理及可用能分析。"}, {"other_code": "N_910946d72ccb23d1", "rule": "本节点关注状态点的性质与描述；兄弟节点关注过程路径（如压缩、膨胀）及循环整体性能。"}], "cross_boundary_rule": "涉及物性数据在循环计算中的应用时，若侧重数据获取、图表读取或状态方程求解，主挂载至本节点；若侧重利用物性进行循环效率或能量流分析，主挂载至“热力过程与动力循环”。"}, {"node_code": "N_e4cbdea8437d2314", "definition": "研究热力学第一、第二定律，能量平衡、熵变、火用分析、不可逆性及可用能评估的理论分支。", "boundary": "聚焦于能量转换的守恒规律、方向性限制及品质分析。涵盖闭口/开口系统能量方程、熵平衡、火用损失计算及热力学效率极限。与“热力学状态与物性”的区别在于：本节点侧重定律推导与能量/熵的流动分析，而非状态参数本身。与“热力过程与动力循环”的区别在于：本节点提供分析工具（如火用分析），兄弟节点应用这些工具于具体循环。", "includes": ["热力学第一定律、能量平衡方程及焓、内能变化分析", "热力学第二定律、熵、熵产及过程方向性判断", "火用（Exergy）、㶲损失、不可逆性及可用能分析"], "excludes": ["具体工质的状态方程与物性图表（归入热力学状态与物性）", "具体动力循环（如朗肯、布雷顿）的结构设计与性能优化（归入热力过程与动力循环）"], "sibling_distinctions": [{"other_code": "N_6a9f5100e2c41f8d", "rule": "本节点研究能量与熵的守恒及变化规律；兄弟节点研究系统状态描述及工质物性数据。"}, {"other_code": "N_910946d72ccb23d1", "rule": "本节点提供通用的能量/熵/火用分析理论与方法；兄弟节点将这些理论应用于具体的压缩、膨胀过程及动力循环。"}], "cross_boundary_rule": "涉及循环中的能量损失分析时，若侧重熵产机理或火用损失的理论计算，主挂载至本节点；若侧重循环整体热效率或特定部件（如涡轮）的性能参数，主挂载至“热力过程与动力循环”。"}, {"node_code": "N_910946d72ccb23d1", "definition": "研究典型热力过程（压缩、膨胀、节流等）及气体、蒸汽、联合及新型动力循环原理与性能分析的分支。", "boundary": "聚焦于工质在设备中经历的具体过程路径及由这些过程构成的循环系统。涵盖理想与真实过程分析、循环热效率、比功计算及新型循环（如超临界、有机朗肯）原理。与“热力学定律”的区别在于：本节点侧重应用定律于具体过程与循环，而非定律本身的推导。与“状态与物性”的区别在于：本节点关注动态过程与系统整体，而非静态状态点。", "includes": ["压缩、膨胀、节流、混合等典型热力过程分析", "气体动力循环（如布雷顿、狄塞尔）及蒸汽动力循环（如朗肯）", "联合循环、热电联产及新型/先进动力循环原理"], "excludes": ["基础热力学定律的数学推导与熵/火用理论定义（归入热力学定律与可用能）", "工质状态方程、物性图表及湿空气性质（归入热力学状态与物性）"], "sibling_distinctions": [{"other_code": "N_6a9f5100e2c41f8d", "rule": "本节点研究过程路径与循环系统；兄弟节点研究状态点描述与工质物性基础。"}, {"other_code": "N_e4cbdea8437d2314", "rule": "本节点应用能量/熵分析于具体循环；兄弟节点研究能量/熵/火用的基本定律与分析方法。"}], "cross_boundary_rule": "涉及循环效率计算时，若侧重循环结构、过程组合及整体性能指标，主挂载至本节点；若侧重循环中某一环节的㶲损失机理或熵产分析，可关联至“热力学定律与可用能”，但主挂载仍为本节点。"}]}
